INSERT INTO chunks (document_id, chunk_index, content, token_count, created_at) SELECT d.id, 0, 'Ung thư đại trực tràng
Thông tin trong tài liệu này chỉ mang tính tham khảo, không thay thế chẩn đoán và chỉ
định điều trị của bác sĩ. Nếu có triệu chứng, hãy đến cơ sở y tế để được khám trực tiếp.', NULL, now() FROM documents d WHERE d.title = '25-ung-thu-dai-truc-trang.pdf';
INSERT INTO chunks (document_id, chunk_index, content, token_count, created_at) SELECT d.id, 1, 'Tổng quan
Ung thư đại trực tràng là ung thư xuất phát từ đại tràng (ruột già) hoặc trực tràng
(đoạn cuối của ruột già, nối với hậu môn). Phần lớn trường hợp bắt đầu từ các
polyp - những khối u nhỏ lành tính mọc trên niêm mạc đại tràng - và sau nhiều
năm, một số polyp có thể biến đổi dần thành ác tính nếu không được phát hiện và
cắt bỏ.
Đây là một trong những loại ung thư phổ biến nhất ở cả nam và nữ trên thế giới,
và tỷ lệ mắc có xu hướng gia tăng ở người dưới 50 tuổi trong những năm gần đây,
dù nguyên nhân của xu hướng này chưa được hiểu rõ hoàn toàn. Điểm đáng
mừng là ung thư đại trực tràng là một trong số ít loại ung thư có thể phòng ngừa
và phát hiện sớm hiệu quả nhờ các chương trình tầm soát, vì quá trình polyp biến
đổi thành ung thư thường diễn ra chậm, kéo dài nhiều năm - đủ thời gian để phát
hiện và xử lý trước khi polyp trở thành ác tính.', NULL, now() FROM documents d WHERE d.title = '25-ung-thu-dai-truc-trang.pdf';
INSERT INTO chunks (document_id, chunk_index, content, token_count, created_at) SELECT d.id, 2, 'Nguyên nhân / Yếu tố nguy cơ
Nguyên nhân chính xác chưa được xác định hoàn toàn, nhưng nhiều yếu tố nguy
cơ đã được ghi nhận rõ, có thể chia thành hai nhóm:', NULL, now() FROM documents d WHERE d.title = '25-ung-thu-dai-truc-trang.pdf';
INSERT INTO chunks (document_id, chunk_index, content, token_count, created_at) SELECT d.id, 3, 'Yếu tố có thể thay đổi được:
Thừa cân, béo phì
Chế độ ăn nhiều thịt đỏ, thịt chế biến sẵn (xúc xích, thịt xông khói...), ít rau củ
quả và chất xơ
Ít vận động thể chất
Hút thuốc lá
Uống rượu bia nhiều, kéo dài
Đái tháo đường type 2', NULL, now() FROM documents d WHERE d.title = '25-ung-thu-dai-truc-trang.pdf';
INSERT INTO chunks (document_id, chunk_index, content, token_count, created_at) SELECT d.id, 4, 'Yếu tố không thể thay đổi:
Tuổi cao (nguy cơ tăng dần sau 45-50 tuổi, nhưng vẫn có thể gặp ở người trẻ
hơn)
Tiền sử gia đình có người mắc ung thư đại trực tràng hoặc polyp tuyến, đặc biệt
nếu người thân được chẩn đoán trước 50 tuổi
Mang hội chứng di truyền như hội chứng Lynch, đa polyp tuyến gia đình (FAP)
Tiền sử cá nhân có polyp đại tràng hoặc từng mắc ung thư đại trực tràng
Mắc bệnh viêm ruột mạn tính (viêm loét đại tràng, bệnh Crohn) kéo dài
Tiền sử xạ trị vùng bụng hoặc vùng chậu', NULL, now() FROM documents d WHERE d.title = '25-ung-thu-dai-truc-trang.pdf';
INSERT INTO chunks (document_id, chunk_index, content, token_count, created_at) SELECT d.id, 5, 'Triệu chứng
Ở giai đoạn sớm, ung thư đại trực tràng có thể hoàn toàn không gây triệu chứng -
đây là lý do tầm soát định kỳ quan trọng hơn là chỉ chờ có dấu hiệu rồi mới đi
khám. Khi bệnh tiến triển, các triệu chứng có thể gồm:
Thay đổi thói quen đại tiện kéo dài trên vài ngày: tiêu chảy, táo bón, hoặc phân
nhỏ hơn bình thường
Cảm giác muốn đi đại tiện nhưng đi xong vẫn không thấy nhẹ bụng
Chảy máu trực tràng, máu đỏ tươi lẫn trong phân
Phân có màu sẫm hoặc đen (gợi ý chảy máu từ đoạn cao hơn)
Đau quặn bụng hoặc đau bụng kéo dài
Mệt mỏi, suy nhược
Sụt cân không rõ nguyên nhân
Nhiều triệu chứng trên khá giống với các bệnh lành tính như trĩ hoặc hội chứng
ruột kích thích, nên dễ bị chủ quan bỏ qua. Nếu triệu chứng kéo dài hơn vài tuần,
nên đi khám để được kiểm tra kỹ, không nên tự chẩn đoán là trĩ hay rối loạn tiêu
hóa thông thường.', NULL, now() FROM documents d WHERE d.title = '25-ung-thu-dai-truc-trang.pdf';
INSERT INTO chunks (document_id, chunk_index, content, token_count, created_at) SELECT d.id, 6, 'Khi nào cần đi khám gấp
Cần đi khám ngay hoặc đến cấp cứu khi có:
Chảy máu trực tràng nhiều hoặc kéo dài
Đau bụng dữ dội, bụng chướng căng
Không trung tiện, không đại tiện được (nghi tắc ruột)
Nôn nhiều, không ăn uống được
Mệt lả, chóng mặt, da nhợt (dấu hiệu thiếu máu nặng do mất máu kéo dài)', NULL, now() FROM documents d WHERE d.title = '25-ung-thu-dai-truc-trang.pdf';
INSERT INTO chunks (document_id, chunk_index, content, token_count, created_at) SELECT d.id, 7, 'Chẩn đoán
Nội soi đại tràng toàn bộ là phương pháp quan trọng nhất: giúp quan sát trực
tiếp toàn bộ đại tràng, phát hiện và có thể cắt bỏ polyp ngay trong lúc soi, đồng
thời sinh thiết các vùng nghi ngờ
Xét nghiệm tìm máu ẩn trong phân (xét nghiệm hóa học hoặc miễn dịch) -
phương pháp sàng lọc không xâm lấn
Xét nghiệm DNA hoặc RNA trong phân - một phương pháp sàng lọc không xâm
lấn khác
Chẩn đoán hình ảnh (CT, MRI, siêu âm) để đánh giá giai đoạn và mức độ lan
rộng sau khi đã xác định có ung thư
Xét nghiệm máu tìm chất chỉ điểm (như CEA) hỗ trợ theo dõi điều trị, không
dùng để chẩn đoán ban đầu', NULL, now() FROM documents d WHERE d.title = '25-ung-thu-dai-truc-trang.pdf';
INSERT INTO chunks (document_id, chunk_index, content, token_count, created_at) SELECT d.id, 8, 'Điều trị
Phương pháp điều trị tùy thuộc vào giai đoạn bệnh, vị trí khối u (đại tràng hay
trực tràng) và tình trạng sức khỏe người bệnh, do bác sĩ chuyên khoa quyết định:
Phẫu thuật là phương pháp điều trị chính cho hầu hết giai đoạn, nhằm cắt bỏ
đoạn ruột chứa khối u và các hạch lân cận. Với polyp hoặc tổn thương rất sớm,
có thể cắt bỏ ngay qua nội soi mà không cần mổ
Hóa trị: dùng thuốc để tiêu diệt tế bào ung thư, có thể dùng trước mổ để thu
nhỏ khối u, sau mổ để giảm nguy cơ tái phát, hoặc cho giai đoạn đã di căn
Xạ trị: thường áp dụng nhiều hơn với ung thư trực tràng, có thể kết hợp với hóa
trị trước phẫu thuật
Thuốc điều trị đích và liệu pháp miễn dịch: áp dụng cho một số trường hợp cụ
thể dựa trên đặc điểm sinh học của khối u
Với giai đoạn di căn, việc điều trị tập trung vào kiểm soát bệnh, kéo dài thời
gian sống và giảm triệu chứng, kết hợp chăm sóc hỗ trợ như giảm đau và hỗ
trợ dinh dưỡng
Người bệnh nên trao đổi kỹ với bác sĩ về lợi ích và nguy cơ của từng phương án, có
thể xin ý kiến thứ hai (second opinion) nếu cần, và tham gia đầy đủ vào quá trình
theo dõi sau điều trị.', NULL, now() FROM documents d WHERE d.title = '25-ung-thu-dai-truc-trang.pdf';
INSERT INTO chunks (document_id, chunk_index, content, token_count, created_at) SELECT d.id, 9, 'Phòng ngừa / Sàng lọc sớm
Đây là loại ung thư mà việc sàng lọc mang lại hiệu quả rõ rệt nhất, vì phát hiện và
cắt bỏ polyp sớm có thể ngăn ung thư hình thành:
Người có nguy cơ trung bình (không có yếu tố nguy cơ đặc biệt) nên bắt đầu
tầm soát từ 45 tuổi, duy trì đến khoảng 75 tuổi; sau tuổi này, quyết định tiếp tục
hay không tùy tình trạng sức khỏe cụ thể
Người có yếu tố nguy cơ cao (tiền sử gia đình, polyp, viêm ruột mạn tính, hội
chứng di truyền) có thể cần tầm soát sớm hơn và thường xuyên hơn - nên hỏi ý
kiến bác sĩ để có lịch phù hợp
Các phương pháp tầm soát phổ biến: nội soi đại tràng (thường mỗi 10 năm nếu
kết quả bình thường), xét nghiệm máu ẩn trong phân (hằng năm), hoặc xét
nghiệm DNA trong phân (mỗi 3 năm) - bác sĩ sẽ tư vấn phương pháp phù hợp
với từng người
Duy trì cân nặng hợp lý, ăn nhiều rau củ quả và chất xơ, hạn chế thịt đỏ và thịt
chế biến sẵn
Tập thể dục thường xuyên, không hút thuốc, hạn chế rượu bia
Điều trị tốt các bệnh viêm ruột mạn tính nếu có, và tuân thủ lịch nội soi theo
dõi do bác sĩ đề ra
Thông điệp quan trọng nhất: dù chọn phương pháp tầm soát nào, điều cốt yếu là
đi tầm soát đúng lịch - đây là cách hiệu quả nhất để phát hiện bệnh ở giai đoạn có
thể điều trị khỏi hoàn toàn, thậm chí ngăn ngừa ung thư hình thành ngay từ
polyp.', NULL, now() FROM documents d WHERE d.title = '25-ung-thu-dai-truc-trang.pdf';
